            aWandererE = aWandererE ^ (((RotL64(aScatter, 60U) + RotL64(aOrbiterC, 19U)) + aOrbiterA) + aWUSaltA[(((511U - aIndex) + 401U)) & S_SALT1]);
            aWandererF = aWandererF + (((RotL64(aPrevious, 41U) + RotL64(aOrbiterB, 43U)) + aOrbiterJ) + aWUSaltF[(((511U - aIndex) + 383U)) & S_SALT1]);
            aWandererD = aWandererD ^ ((RotL64(aCross, 29U) + aOrbiterA) + RotL64(aOrbiterD, 27U));
            aWandererA = aWandererA + (((RotL64(aIngress, 37U) + RotL64(aOrbiterE, 6U)) + aOrbiterH) + RotL64(aCarry, 23U));
            aWandererK = aWandererK ^ ((RotL64(aCross, 19U) + aOrbiterD) + RotL64(aOrbiterI, 39U));
            //
            aCarry = aCarry + (aWandererF ^ RotL64(aWandererJ, 52U));
