            aCross = (RotL64(aWaterLaneC[((S_BLOCK1 - aIndex + 7101U)) & S_BLOCK1], 37U) ^ RotL64(aWaterLaneA[((S_BLOCK1 - aIndex + 4758U)) & S_BLOCK1], 53U));
            aCross ^= (RotL64(pCrossLaneB[((S_BLOCK1 - aIndex + 5792U)) & S_BLOCK1], 14U) ^ RotL64(aKeyRowReadA[(((2047U - aIndex) + 3854U)) & W_KEY1], 29U));
            aCross = TwistMix64::DiffuseA((aCross ^ aTwistDomainWordCross));
            //
            aScatter = (RotL64(aIngress, 60U) + RotL64(aCross, 23U)) + (RotL64(aCarry, 43U) ^ RotL64(aPrevious, 11U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterG = (((aWandererE + RotL64(aCross, 11U)) + RotL64(aCarry, 35U)) + 0x592052319D8312A9ULL) + aOASaltF[(((511U - aIndex) + 93U)) & S_SALT1];
            aOrbiterB = ((aWandererB + RotL64(aIngress, 43U)) + 0x96FD6ECDEF80AB59ULL) + aOASaltA[((aIndex + 141U)) & S_SALT1];
            aOrbiterI = (aWandererJ + RotL64(aPrevious, 50U)) + 0x6B28AFAB568CD6BAULL;
            aOrbiterK = (aWandererH + RotL64(aScatter, 57U)) + 0x4D74FA3CD1D20762ULL;
            aOrbiterH = ((aWandererF + RotL64(aCross, 35U)) + 0x661C92C629694308ULL) + aOASaltD[(((511U - aIndex) + 256U)) & S_SALT1];
            aOrbiterC = (((aWandererD + RotL64(aIngress, 27U)) + RotL64(aCarry, 13U)) + 0x9FCBD10A36AA51EBULL) + aOASaltG[(((511U - aIndex) + 127U)) & S_SALT1];
            aOrbiterE = (((aWandererC + RotL64(aScatter, 5U)) + RotL64(aCarry, 53U)) + 0x91011E64C9F014F6ULL) + aOASaltC[(((511U - aIndex) + 490U)) & S_SALT1];
            //
            aOrbiterG = ((aOrbiterG + aOrbiterB) + 0x13D99B1B0AFC8CD7ULL) + aOUSaltC[((aIndex + 157U)) & S_SALT1];
            aOrbiterI = ((aOrbiterI ^ aOrbiterG) ^ 0xF160712E3F4694CCULL) ^ aOUSaltH[(((511U - aIndex) + 511U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0xD7CD563FB0EADF9BULL), 21U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterK) + 0xDE713319B4625667ULL) + aOUSaltD[(((511U - aIndex) + 364U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterI) ^ 0x67AC0A4617DAC1ECULL;
            aOrbiterH = RotL64((aOrbiterH * 0xA4EB52980BF90593ULL), 5U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterC) + 0x7C7BE35F1079C044ULL) + aOUSaltE[((aIndex + 169U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterH) ^ 0xF0D8B4049CA7F7A9ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x8155F1A2C168BA9BULL), 57U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterG) + 0x75693A4999C4C0D1ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterK) ^ 0x7843106DAE07CDD1ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x876D7BF4D65E3D4DULL), 13U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterI) + 0x2C7CBA1F73A4E5EBULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterC) ^ 0xC358A6B51931E17AULL) ^ aOUSaltA[(((511U - aIndex) + 208U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x0FCDA060F456580DULL), 29U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterE) + 0x1998115AED12CDC1ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterB) ^ 0x1832D8D7A53D1F1CULL;
            aOrbiterK = RotL64((aOrbiterK * 0xDA6D690E09F4668FULL), 41U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterH) + 0x8532131BBE43C74DULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterE) ^ 0xD62147C67A89FA89ULL) ^ aOUSaltG[((aIndex + 41U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0xD985ADA4E8FB879DULL), 51U);
            //
            aIngress = aOrbiterG ^ RotL64(aOrbiterH, 23U);
