            aWandererC = aWandererC + ((((RotL64(aCross, 21U) + aOrbiterC) + RotL64(aOrbiterK, 57U)) + RotL64(aCarry, 13U)) + aWUSaltC[((aIndex + 359U)) & S_SALT1]);
            aWandererH = aWandererH ^ (((RotL64(aScatter, 14U) + aOrbiterC) + RotL64(aOrbiterI, 21U)) + aWUSaltG[((aIndex + 325U)) & S_SALT1]);
            aWandererD = aWandererD + (((RotL64(aIngress, 5U) + aOrbiterC) + RotL64(aOrbiterH, 48U)) + RotL64(aCarry, 29U));
            aWandererB = aWandererB ^ (((RotL64(aCross, 39U) + RotL64(aOrbiterB, 13U)) + aOrbiterG) + aWUSaltA[(((511U - aIndex) + 370U)) & S_SALT1]);
            aWandererE = aWandererE + (((RotL64(aScatter, 57U) + RotL64(aOrbiterI, 3U)) + aOrbiterG) + aWUSaltE[((aIndex + 403U)) & S_SALT1]);
            //
            aCarry = aCarry + (RotL64(aWandererE, 23U) ^ aWandererD);
