            aWandererC = aWandererC + ((RotL64(aCross, 47U) + aOrbiterD) + RotL64(aOrbiterF, 19U));
            aWandererI = aWandererI ^ ((RotL64(aPrevious, 5U) + RotL64(aOrbiterI, 37U)) + aOrbiterJ);
