            aOrbiterG = (aWandererF + RotL64(aScatter, 13U)) + 0xB6E574A5E0EA6F97ULL;
            aOrbiterD = (aWandererC + RotL64(aCross, 19U)) + 0xB83436EC766C6778ULL;
            //
            aOrbiterC = (aOrbiterC + aOrbiterI) + 0xF035F5E98E285E12ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterC) ^ 0x4BBB0A3D36628919ULL;
