            aOrbiterI = (aOrbiterI + aOrbiterB) + 0x2EAD5231859AAA20ULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterI) ^ 0xD620AD95FA6BF055ULL) ^ aOUSaltH[((aIndex + 478U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x58B8184448324843ULL), 39U);
