            aWandererK = aWandererK + ((((RotL64(aIngress, 35U) + aOrbiterA) + RotL64(aOrbiterJ, 3U)) + RotL64(aCarry, 57U)) + aWUSaltB[((aIndex + 215U)) & S_SALT1]);
            aWandererB = aWandererB ^ (((RotL64(aCross, 29U) + aOrbiterF) + RotL64(aOrbiterI, 21U)) + aWUSaltC[(((511U - aIndex) + 448U)) & S_SALT1]);
            aWandererG = aWandererG + ((((RotL64(aScatter, 13U) + RotL64(aOrbiterJ, 6U)) + aOrbiterK) + RotL64(aCarry, 41U)) + aWUSaltD[((aIndex + 355U)) & S_SALT1]);
            aWandererI = aWandererI ^ ((RotL64(aIngress, 48U) + aOrbiterK) + RotL64(aOrbiterI, 47U));
            //
            aCarry = aCarry + (aWandererH ^ RotL64(aWandererG, 24U));
