            aOrbiterI = (((aWandererD + RotL64(aIngress, 19U)) + RotL64(aCarry, 35U)) + 0xDD2BC768369E1F08ULL) + aOASaltE[((aIndex + 386U)) & S_SALT1];
            aOrbiterD = ((aWandererA + RotL64(aCross, 35U)) + 0xD5A09C45FC862E13ULL) + aOASaltA[(((511U - aIndex) + 225U)) & S_SALT1];
            aOrbiterC = (((aWandererG + RotL64(aPrevious, 29U)) + RotL64(aCarry, 19U)) + 0x954517DBCCED32E6ULL) + aOASaltC[((aIndex + 41U)) & S_SALT1];
