            aScatter = (RotL64(aCarry, 5U) + RotL64(aPrevious, 39U)) + (RotL64(aCross, 57U) ^ RotL64(aIngress, 24U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterE = (aWandererG + RotL64(aCross, 57U)) + 0x6D79C9C6DE1D1EE9ULL;
            aOrbiterA = (((aWandererA + RotL64(aScatter, 28U)) + RotL64(aCarry, 21U)) + 0x701AD4E95825D3CBULL) + aOASaltA[((aIndex + 42U)) & S_SALT1];
