            aOrbiterH = (((aWandererB + RotL64(aPrevious, 51U)) + RotL64(aCarry, 3U)) + 0xE61385B231570F41ULL) + aOASaltC[(((511U - aIndex) + 207U)) & S_SALT1];
            aOrbiterC = (aWandererC + RotL64(aCross, 35U)) + 0xFD347727157AC909ULL;
            aOrbiterF = ((aWandererE + RotL64(aIngress, 13U)) + 0x2C4EA8B336D24E31ULL) + aOASaltF[(((511U - aIndex) + 81U)) & S_SALT1];
