            aOrbiterJ = ((aOrbiterJ + aOrbiterD) + 0x051E890D019A720BULL) + aOUSaltE[((aIndex + 62U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterJ) ^ 0x70CABF90F0D20C35ULL;
