            aOrbiterC = RotL64((aOrbiterC * 0xCD090430274709C7ULL), 57U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterH) + 0x4BE9B9662C066B3AULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterC) ^ 0x8B984F0E28832C99ULL;
            aOrbiterE = RotL64((aOrbiterE * 0xA3E74D3A9C5F8B99ULL), 3U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterF) + 0x885FB25193C9EFA8ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterH) ^ 0x191F311B3434E83CULL;
