            //
            aOrbiterF = ((aOrbiterF + aOrbiterE) + 0xC7AE9BD6981CF74EULL) + aOUSaltH[(((511U - aIndex) + 221U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterF) ^ 0x5B5BC35AEDF9440BULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xCB03F0288BB4DC93ULL), 13U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterC) + 0xADCDD69BBD05B666ULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterD) ^ 0xC770A3407B754BC6ULL) ^ aOUSaltG[((aIndex + 507U)) & S_SALT1];
