            aWandererB = aWandererB + ((((RotL64(aIngress, 11U) + RotL64(aOrbiterF, 21U)) + aOrbiterD) + RotL64(aCarry, 41U)) + aWUSaltG[((aIndex + 427U)) & S_SALT1]);
