            aCross = (RotL64(aFuseLaneA[((S_BLOCK1 - aIndex + 16717U)) & S_BLOCK1], 57U) ^ RotL64(aWindLaneC[((S_BLOCK1 - aIndex + 19878U)) & S_BLOCK1], 37U));
            aCross ^= (RotL64(aSoilLaneA[((S_BLOCK1 - aIndex + 16422U)) & S_BLOCK1], 12U) ^ RotL64(aCrystalLaneB[((aIndex + 22022U)) & S_BLOCK1], 23U));
            aCross = TwistMix64::DiffuseB((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aIngress, 35U) + RotL64(aCross, 47U)) + (RotL64(aPrevious, 23U) ^ RotL64(aCarry, 4U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterF = (((aWandererE + RotL64(aScatter, 13U)) + RotL64(aCarry, 41U)) + 0xDEF9EADFDA03CAE0ULL) + aOASaltH[(((511U - aIndex) + 263U)) & S_SALT1];
            aOrbiterB = (((aWandererI + RotL64(aIngress, 51U)) + RotL64(aCarry, 53U)) + 0x5A8F5111E4AA10C1ULL) + aOASaltF[(((511U - aIndex) + 489U)) & S_SALT1];
            aOrbiterC = (aWandererB + RotL64(aPrevious, 3U)) + 0xE2F59D6892DD9325ULL;
            aOrbiterK = (aWandererG + RotL64(aCross, 27U)) + 0xA772D81F42F2C352ULL;
            aOrbiterH = ((aWandererD + RotL64(aIngress, 60U)) + 0x2E43BC59ECDA3D81ULL) + aOASaltB[(((511U - aIndex) + 326U)) & S_SALT1];
            aOrbiterG = (((aWandererK + RotL64(aCross, 43U)) + RotL64(aCarry, 27U)) + 0x346294113A4FDAEAULL) + aOASaltA[(((511U - aIndex) + 204U)) & S_SALT1];
            aOrbiterD = ((aWandererA + RotL64(aPrevious, 35U)) + 0x77549BE55B6E96EBULL) + aOASaltC[(((511U - aIndex) + 212U)) & S_SALT1];
            //
            aOrbiterF = (aOrbiterF + aOrbiterB) + 0x5DC49BC8735957BDULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterF) ^ 0x06654AD65E53BC17ULL) ^ aOUSaltF[((aIndex + 241U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0xCC90F990A892B6E5ULL), 37U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterK) + 0x351B16DCA4741571ULL) + aOUSaltG[(((511U - aIndex) + 207U)) & S_SALT1];
            aOrbiterH = ((aOrbiterH ^ aOrbiterC) ^ 0x7ECCBF0C70281BEAULL) ^ aOUSaltC[((aIndex + 279U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x4D440F8F57DE8F4DULL), 43U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterD) + 0x561CAED6FBD821D3ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterG) ^ 0x12E260CF7C4442F3ULL;
            aOrbiterF = RotL64((aOrbiterF * 0xAD25C2502628F7D3ULL), 29U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterF) + 0x40AB8130B470202EULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterD) ^ 0xB20EB70E4128145CULL;
            aOrbiterB = RotL64((aOrbiterB * 0xEBDEE1451A81564FULL), 51U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterG) + 0xAABAA4066C6BCDF9ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterH) ^ 0x11C1074915F378A7ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xC3B2120855B24329ULL), 57U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterC) + 0xD0CFB653AD78E619ULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterB) ^ 0x391ACB1911CF93CCULL) ^ aOUSaltB[((aIndex + 211U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0xAA9FB76C1262EF09ULL), 13U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterH) + 0x68EA9365D783A117ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterK) ^ 0x7378332337559745ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x7AE4B23D51CD1231ULL), 5U);
            //
            aIngress = aOrbiterC ^ RotL64(aOrbiterH, 29U);
            aIngress = aIngress + (aOrbiterG ^ RotL64(aOrbiterB, 58U));
            aIngress = aIngress + (aOrbiterF ^ RotL64(aOrbiterK, 37U));
            aIngress = aIngress + RotL64(aOrbiterD, 21U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererD = aWandererD ^ (((RotL64(aCross, 5U) + RotL64(aOrbiterG, 21U)) + aOrbiterK) + aWUSaltG[((aIndex + 163U)) & S_SALT1]);
            aWandererB = aWandererB + (((RotL64(aIngress, 46U) + RotL64(aOrbiterD, 13U)) + aOrbiterH) + RotL64(aCarry, 21U));
            aWandererK = aWandererK ^ (((RotL64(aPrevious, 53U) + RotL64(aOrbiterH, 60U)) + aOrbiterG) + aWUSaltA[(((511U - aIndex) + 22U)) & S_SALT1]);
            aWandererG = aWandererG + ((((RotL64(aScatter, 21U) + aOrbiterC) + RotL64(aOrbiterH, 53U)) + RotL64(aCarry, 41U)) + aWUSaltB[((aIndex + 482U)) & S_SALT1]);
            aWandererI = aWandererI ^ (((RotL64(aIngress, 13U) + RotL64(aOrbiterB, 47U)) + aOrbiterC) + aWUSaltE[((aIndex + 145U)) & S_SALT1]);
