            //
            aIngress = (RotL64(aFuseLaneC[((aIndex + 31312U)) & S_BLOCK1], 22U) ^ RotL64(aFuseLaneA[((aIndex + 30874U)) & S_BLOCK1], 41U));
            aIngress ^= (RotL64(aCrystalLaneD[((aIndex + 24904U)) & S_BLOCK1], 53U) ^ RotL64(aKeyRowReadB[(((2047U - aIndex) + 28501U)) & W_KEY1], 11U));
            aIngress = TwistMix64::DiffuseC((aIngress ^ aKeyRotateADomainWordIngress));
            //
            aCross = (RotL64(aFuseLaneB[((S_BLOCK1 - aIndex + 25806U)) & S_BLOCK1], 58U) ^ RotL64(aWindLaneD[((S_BLOCK1 - aIndex + 25229U)) & S_BLOCK1], 3U));
            aCross ^= (RotL64(aShadowLaneD[((S_BLOCK1 - aIndex + 29495U)) & S_BLOCK1], 37U) ^ RotL64(aPlasmaLaneD[((S_BLOCK1 - aIndex + 25318U)) & S_BLOCK1], 47U));
            aCross = TwistMix64::DiffuseB((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aCross, 13U) + RotL64(aPrevious, 56U)) ^ (RotL64(aCarry, 43U) + RotL64(aIngress, 27U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterC = ((aWandererH + RotL64(aCross, 60U)) + 0x9C6347F66EA549D2ULL) + aOASaltF[((aIndex + 47U)) & S_SALT1];
            aOrbiterF = (((aWandererB + RotL64(aIngress, 3U)) + RotL64(aCarry, 5U)) + 0xA7B559747EE5CD5BULL) + aOASaltB[(((511U - aIndex) + 261U)) & S_SALT1];
            aOrbiterD = (aWandererD + RotL64(aPrevious, 35U)) + 0x44F1F3EC5D0BC145ULL;
            aOrbiterI = (aWandererJ + RotL64(aScatter, 53U)) + 0xB80E82A437132A76ULL;
            aOrbiterJ = ((aWandererK + RotL64(aIngress, 41U)) + 0xADECC084FEBB0DCAULL) + aOASaltE[(((511U - aIndex) + 446U)) & S_SALT1];
            aOrbiterH = (((aWandererG + RotL64(aPrevious, 21U)) + RotL64(aCarry, 19U)) + 0xEE092168DD84C679ULL) + aOASaltA[(((511U - aIndex) + 248U)) & S_SALT1];
            aOrbiterA = (((aWandererF + RotL64(aCross, 11U)) + RotL64(aCarry, 47U)) + 0x65364EB4AC108791ULL) + aOASaltH[(((511U - aIndex) + 378U)) & S_SALT1];
            //
            aOrbiterC = ((aOrbiterC + aOrbiterF) + 0xC0B4B1F7BBF7EB82ULL) + aOUSaltD[((aIndex + 431U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterC) ^ 0x65DC7A049CA28F6CULL;
            aOrbiterD = RotL64((aOrbiterD * 0x8569C5688A885D4BULL), 51U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterJ) + 0xC22FC3D675E433EDULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterI) ^ 0xE42E650A1AAA9FB7ULL) ^ aOUSaltA[(((511U - aIndex) + 119U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0xF882BB01E957542DULL), 11U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterA) + 0x6D38FCBCA997597AULL) + aOUSaltF[((aIndex + 354U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterD) ^ 0x663197F0B4D9C5A3ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x28C5B617BB058FC9ULL), 21U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterH) + 0xFA6D68C32B4D4289ULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterJ) ^ 0xE2BDA48A8B29E50BULL) ^ aOUSaltC[(((511U - aIndex) + 411U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x702D25DA025232AFULL), 57U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterI) + 0x250E81A86E521810ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterA) ^ 0xF07A275660D90FDAULL) ^ aOUSaltE[(((511U - aIndex) + 51U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x125B304A11C9539DULL), 43U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterC) + 0x8F2EA6BF559DE97DULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterH) ^ 0x60F71A6809C193CDULL;
            aOrbiterF = RotL64((aOrbiterF * 0x4E0A11C94F5CC7ADULL), 27U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterD) + 0x49E3AAC856A672D5ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterF) ^ 0xA7A30BA64E9015E6ULL) ^ aOUSaltB[(((511U - aIndex) + 7U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x9DBFB2ECC71E5F29ULL), 3U);
            //
            aIngress = RotL64(aOrbiterI, 47U) ^ aOrbiterJ;
