            aWandererG = aWandererG + (((RotL64(aPrevious, 35U) + aOrbiterJ) + RotL64(aOrbiterD, 60U)) + RotL64(aCarry, 41U));
            aWandererF = aWandererF ^ (((RotL64(aScatter, 19U) + RotL64(aOrbiterI, 51U)) + aOrbiterD) + aWUSaltG[((aIndex + 206U)) & S_SALT1]);
            aWandererB = aWandererB + (((RotL64(aIngress, 13U) + aOrbiterF) + RotL64(aOrbiterD, 11U)) + aWUSaltD[((aIndex + 184U)) & S_SALT1]);
            aWandererD = aWandererD ^ (((RotL64(aCross, 42U) + aOrbiterA) + RotL64(aOrbiterD, 35U)) + aWUSaltH[((aIndex + 85U)) & S_SALT1]);
            aWandererK = aWandererK + ((RotL64(aScatter, 51U) + RotL64(aOrbiterD, 19U)) + aOrbiterC);
            aWandererJ = aWandererJ ^ (((RotL64(aPrevious, 3U) + aOrbiterH) + RotL64(aOrbiterC, 27U)) + aWUSaltA[((aIndex + 77U)) & S_SALT1]);
            aWandererH = aWandererH + (((RotL64(aCross, 29U) + RotL64(aOrbiterJ, 3U)) + aOrbiterH) + RotL64(aCarry, 29U));
