            //
            aOrbiterD = (((aWandererJ + RotL64(aIngress, 13U)) + RotL64(aCarry, 29U)) + 0x4A9539C0E2287C9CULL) + aOASaltH[(((511U - aIndex) + 133U)) & S_SALT1];
